  'ath.lot': { hook: '**By lot** = by luck of the draw, like names from a hat. Athens even had a stone machine for it, the kleroterion.', example: 'Jurors in England are still chosen by lot: picked at random from the list of voters.' },
  'ath.pericles': { hook: '**P**ericles built the **P**arthenon: two Ps on the Acropolis.' },
  'ath.parthenon': { hook: '**Athena** gave her name to **Athens**; Parthenon comes from **parthenos**, maiden, one of her titles.', example: 'The unfinished National Monument on Calton Hill in Edinburgh was modelled on the Parthenon.' },
  'ath.agora': { hook: '**Agora**phobia is a fear of open, crowded places: the agora was the city’s open, crowded square.' },
  // Sparta
  'sp.agoge': { hook: '**Agoge** comes from the Greek for “to lead”, like ped**agog**y, the art of teaching children.' },
  'sp.helots': { hook: 'Herodotus says seven helots marched beside each Spartan at Plataea: a clue to how many there were.' },
  'sp.kings': { hook: '**Two** kings so neither could rule alone, plus five elected **ephors** to keep watch on them.' },
  'sp.women': { hook: 'Asked why Spartan women ruled their men, Queen Gorgo is said to have replied: “Because only we give birth to men.”' },
  'sp.why': { hook: 'Sparta’s army faced **inwards** as much as outwards: the great fear was a helot revolt.' },
  'sp.war': { hook: '**Peloponnese** = “island of Pelops”, Sparta’s home peninsula. **431 to 404 BC**: a 27-year war.' },
  'sp.phalanx': { hook: 'Your shield guards your neighbour: in a **phalanx**, nobody is safe unless everyone holds the line.', example: 'The bones of your fingers and toes are called phalanges, named after the rows of a phalanx.' },
