  'pw.darius': { hook: '**D** before **X**: Darius (490 BC) came first, then his son Xerxes (480 BC): alphabetical and in time order.' },
  'pw.leonidas': { hook: '**Leonidas** means “son of the lion”: a lion-hearted king for a famous last stand.', example: 'A bronze statue of Leonidas stands at Thermopylae, with his reply to the Persians: “Come and take them”.' },
  'pw.thermo': { hook: 'Thermopylae means “**hot gates**”, after its hot springs: a narrow gate, until a traitor showed the back door.' },
