  'pw.why': { hook: 'A crowd in a narrow corridor cannot turn round: that is what happened to the Persian ships.' },
  'pw.trireme': { hook: '**Tri** = three, as in triangle and tricycle: three rows of oars on each side.', example: 'A full-size working trireme, the Olympias, was built in the 1980s and rowed at sea by volunteer crews.' },
